{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Replaces the definition of \"Bullying\" in Tennessee Code Annotated, Section 39-17-308(e)(1), with an act committed by a school employee or student that substantially interferes with a victim's educational benefits, opportunities, or performance and meets location-specific conditions. On school grounds, at a school-sponsored activity, on school-provided equipment or transportation, or at an official school bus stop, the act must physically harm the victim or damage the victim's property, or knowingly place the victim or victims in reasonable fear of physical harm to the victim or damage to the victim's property. Off school property or outside a school-sponsored activity, the act must be directed specifically at a victim or victims and create a substantial disruption to the education environment or learning process.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "\"Bullying\" means an act committed by a school employee or student that"
    },
    {
      "id": "P2",
      "proposition": "Adds a definition of \"School employee\" to Section 39-17-308(e), covering employees of private schools, LEAs, public charter schools, and other public schools.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "\"School employee\" means an employee of a private school, an LEA, a public"
    },
    {
      "id": "P3",
      "proposition": "Adds a definition of \"Victim\" to Section 39-17-308(e): any student when the act is committed by a school employee, and another student when the act is committed by a student.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "(A) If the act is committed by a school employee, then any student; and"
    },
    {
      "id": "P4",
      "proposition": "Amends Tennessee Code Annotated, Section 49-6-4503(b)(3), by adding \"and school employee\" after \"each student\".",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "adding \"and school employee\" after \"each student\"."
    },
    {
      "id": "P5",
      "proposition": "Adds Section 49-6-4503(e), making a teacher or school employee found to have committed harassment, intimidation, bullying, or cyberbullying subject to dismissal or suspension.",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "harassment, intimidation, bullying, or cyberbullying is subject to dismissal or suspension."
    },
    {
      "id": "P6",
      "proposition": "Adds subdivision (E) to Tennessee Code Annotated, Section 49-5-501(7), specifying committing an act of harassment, intimidation, bullying, or cyberbullying in violation of the school district's policy adopted in accordance with Title 49, Chapter 6, Part 45.",
